  1	// see pdf 'ex6 & 7 documentation' for excercise question
  2	
  3	datatype Bases = A | C | G | T
  4	
  5	//swaps two sequence indexes
  6	method Exchanger(s: seq<Bases>, x:nat, y:nat) returns (t: seq<Bases>)
  7	requires 0 < |s| && x < (|s|) + 1 && y < |s|
  8	ensures |t| == |s|
  9	ensures forall b:nat :: 0 <= b < |s| && b != x && b != y ==> t[b] == s[b]
 10	ensures t[x] == s[y] && s[x] == t[y]
 11	ensures multiset(s) == multiset(t)
 12	{
 13	    t := s;
 14	    t := t[ x := s[y]];
 15	    t := t[ y := s[x] ];
 16	    return t;
 17	}
 18	
 19	//idea from Rustan Leino video "Basics of specification and verification: Lecture 3, the Dutch National Flag algorithm"
 20	//modified for 4 elements
 21	predicate below(first: Bases, second: Bases)
 22	{
 23	    first == second ||
 24	    first == A || 
 25	    (first == C && (second ==  G || second == T)) || 
 26	    (first == G && second == T) ||
 27	    second == T
 28	}
 29	
 30	//checks if a sequence is in base order
 31	predicate bordered(s:seq<Bases>)
 32	{
 33	    forall j, k :: 0 <= j < k < |s| ==> below(s[j], s[k])
 34	}
 35	
 36	method Sorter(bases: seq<Bases>) returns (sobases:seq<Bases>)
 37	requires 0 < |bases|
 38	ensures |sobases| == |bases|
 39	ensures bordered(sobases)
 40	ensures multiset(bases) == multiset(sobases);
 41	{
 42	
 43	    sobases := bases;
 44	    var c, next:nat := 0, 0;
 45	    var g, t:nat := |bases|, |bases|;
 46	
 47	    while next != g
 48	    invariant 0 <= c <= next <= g <= t <= |bases|
 49	    invariant |sobases| == |bases|
 50	    invariant multiset(bases) == multiset(sobases);
 51	    invariant forall i:nat :: 0 <= i < c ==> sobases[i] == A
 52	    invariant forall i:nat :: c <= i < next ==> sobases[i] == C
 53	    invariant forall i:nat :: g <= i < t ==> sobases[i] == G
 54	    invariant forall i:nat :: t <= i < |bases| ==> sobases[i] == T
 55	    {
 56	        match(sobases[next]) {
 57	            case C => next := next + 1;
 58	            case A => sobases := Exchanger(sobases, next, c);
 59	                    c, next:= c + 1, next + 1;
 60	            case G => g := g - 1;
 61	                    sobases := Exchanger(sobases, next, g);
 62	            case T => g , t:= g - 1, t - 1;
 63	                    sobases := Exchanger(sobases, next, t);
 64	                    if (g != t) {sobases := Exchanger(sobases, next, g);}
 65	        }
 66	    }
 67	
 68	    return sobases;
 69	}
 70	
 71	method Testerexchange() {
 72	    var a:seq<Bases> := [A, C, A, T]; 
 73	    var b:seq<Bases> := Exchanger(a, 2, 3);
 74	    assert b == [A, C, T, A];
 75	
 76	    var c:seq<Bases> := [A, C, A, T, A, T, C];     
 77	    var d:seq<Bases> := Exchanger(c, 5, 1); 
 78	    assert d == [A, T, A, T, A, C, C];            
 79	
 80	    var e:seq<Bases> := [A, C, A, T, A, T, C];     
 81	    var f:seq<Bases> := Exchanger(e, 1, 1); 
 82	    assert f == [A, C, A, T, A, T, C]; 
 83	
 84	    var g:seq<Bases> := [A, C];     
 85	    var h:seq<Bases> := Exchanger(g, 0, 1); 
 86	    assert h == [C, A]; 
 87	}
 88	
 89	method Testsort() {
 90	
 91	    var a:seq<Bases> := [G,A,T];
 92	    assert a == [G,A,T];
 93	    var b:seq<Bases> := Sorter(a);
 94	    assert bordered(b);
 95	    assert multiset(b) == multiset(a);
 96	
 97	    var c:seq<Bases> := [G, A, T, T, A, C, G, C, T, A, C, G, T, T, G];
 98	    assert c == [G, A, T, T, A, C, G, C, T, A, C, G, T, T, G];
 99	    var d:seq<Bases> := Sorter(c);
100	    assert bordered(d);
101	    assert multiset(c) == multiset(d);
102	
103	    var e:seq<Bases> := [A];
104	    assert e == [A];
105	    var f:seq<Bases> := Sorter(e);
106	    assert bordered(b);
107	    assert multiset(e) == multiset(f);
108	
109	    var g:seq<Bases> := [A, C, G, T];
110	    assert g == [A, C, G, T];
111	    var h:seq<Bases> := Sorter(g);
112	    assert bordered(b);
113	    assert multiset(g) == multiset(h);
114	
115	    var i:seq<Bases> := [A, T, C, T, T];
116	    assert i[0]==A && i[1]==T && i[2]==C && i[3]==T && i[4]==T;
117	    assert !bordered(i);
118	}
